150	function safeHours(value: unknown) {
151	  const number = Number(value);
152	  return Number.isFinite(number) ? Math.max(0, number) : 0;
153	}
154	
155	function isCourseAllocation(
156	  value: unknown,
157	): value is TrainingPlanCourseAllocation {
158	  return Boolean(
159	    value &&
160	      typeof value === 'object' &&
161	      typeof (value as TrainingPlanCourseAllocation).id === 'string' &&
162	      typeof (value as TrainingPlanCourseAllocation).name === 'string',
163	  );
164	}
