166	export function getTrainingPlanCourseAllocations(
167	  fundingDetails: Record<string, unknown> | null | undefined,
168	) {
169	  const details = fundingDetails as
170	    | TrainingPlanFundingDetails
171	    | null
172	    | undefined;
173	  return Array.isArray(details?.courseAllocations)
174	    ? details.courseAllocations.filter(isCourseAllocation)
175	    : [];
176	}
