178	function isAllocationAdjustmentHistoryEntry(
179	  value: unknown,
180	): value is TrainingPlanAllocationAdjustmentHistoryEntry {
181	  return Boolean(
182	    value &&
183	      typeof value === 'object' &&
184	      typeof (value as TrainingPlanAllocationAdjustmentHistoryEntry).id ===
185	        'string' &&
186	      typeof (value as TrainingPlanAllocationAdjustmentHistoryEntry)
187	        .allocationId === 'string' &&
188	      typeof (value as TrainingPlanAllocationAdjustmentHistoryEntry).reason ===
189	        'string',
190	  );
191	}
