273	export function applyHoursToSelectedTrainingPlanCourse(
274	  fundingDetails: Record<string, unknown> | null | undefined,
275	  allocationId: string,
276	  hours: TrainingPlanEventHours,
277	) {
278	  const details: TrainingPlanFundingDetails = { ...(fundingDetails ?? {}) };
279	  const courseAllocations = getTrainingPlanCourseAllocations(details).map(
280	    (allocation) => ({ ...allocation }),
281	  );
282	  const selectedIndex = courseAllocations.findIndex(
283	    (allocation) => allocation.id === allocationId,
284	  );
285	
286	  if (selectedIndex < 0) {
287	    return {
288	      applied: false,
289	      selectedCourseName: null,
290	      fundingDetails: details,
291	    };
292	  }
293	
294	  const selected = courseAllocations[selectedIndex];
295	  selected.flightHoursUsed =
296	    safeHours(selected.flightHoursUsed) + safeHours(hours.flight);
297	  selected.groundHoursUsed =
298	    safeHours(selected.groundHoursUsed) + safeHours(hours.ground);
299	  selected.simulatorHoursUsed =
300	    safeHours(selected.simulatorHoursUsed) + safeHours(hours.simulator);
301	
302	  const flightComplete =
303	    safeHours(selected.flightHoursTotal) === 0 ||
304	    selected.flightHoursUsed >= safeHours(selected.flightHoursTotal);
305	  const groundComplete =
306	    safeHours(selected.groundHoursTotal) === 0 ||
307	    selected.groundHoursUsed >= safeHours(selected.groundHoursTotal);
308	  const simulatorComplete =
309	    safeHours(selected.simulatorHoursTotal) === 0 ||
310	    selected.simulatorHoursUsed >= safeHours(selected.simulatorHoursTotal);
311	
312	  if (selected.status === 'active') {
313	    selected.status =
314	      flightComplete && groundComplete && simulatorComplete
315	        ? 'hours_complete'
316	        : 'active';
317	  }
318	
319	  details.courseAllocations = courseAllocations;
320	  return {
321	    applied: true,
322	    selectedCourseName: selected.name,
323	    fundingDetails: details,
324	  };
325	}
