334	export function manuallyActivateNextTrainingPlanCourse(
335	  fundingDetails: Record<string, unknown> | null | undefined,
336	  allocationId: string,
337	  activation: {
338	    id: string;
339	    activatedAt?: string;
340	    activatedBy?: TrainingPlanCourseActivationHistoryEntry['activatedBy'];
341	  },
342	) {
343	  const details: TrainingPlanFundingDetails = { ...(fundingDetails ?? {}) };
344	  const courseAllocations = getTrainingPlanCourseAllocations(details).map(
345	    (allocation) => ({ ...allocation }),
346	  );
347	  if (courseAllocations.length === 0) {
348	    return {
349	      advanced: false,
350	      reason: 'no_course_allocations' as const,
351	      previousCourseName: null,
352	      activeCourseName: null,
353	      fundingDetails: details,
354	    };
355	  }
356	
357	  const requestedIndex = Number(details.currentCourseIndex);
358	  const currentCourseIndex = Number.isInteger(requestedIndex)
359	    ? Math.min(Math.max(requestedIndex, 0), courseAllocations.length - 1)
360	    : Math.max(
361	        0,
362	        courseAllocations.findIndex(
363	          (allocation) => allocation.status === 'active',
364	        ),
365	      );
366	  const selectedIndex = courseAllocations.findIndex(
367	    (allocation) => allocation.id === allocationId,
368	  );
369	  if (selectedIndex < 0) {
370	    return {
371	      advanced: false,
372	      reason: 'allocation_not_found' as const,
373	      previousCourseName: courseAllocations[currentCourseIndex]?.name ?? null,
374	      activeCourseName: null,
375	      fundingDetails: details,
376	    };
377	  }
378	  if (selectedIndex === currentCourseIndex) {
379	    return {
380	      advanced: false,
381	      reason: 'already_active' as const,
382	      previousCourseName: courseAllocations[currentCourseIndex]?.name ?? null,
383	      activeCourseName: courseAllocations[selectedIndex]?.name ?? null,
384	      fundingDetails: details,
385	    };
386	  }
387	  if (selectedIndex !== currentCourseIndex + 1) {
388	    return {
389	      advanced: false,
390	      reason: 'not_next_course' as const,
391	      previousCourseName: courseAllocations[currentCourseIndex]?.name ?? null,
392	      activeCourseName: courseAllocations[selectedIndex]?.name ?? null,
393	      fundingDetails: details,
394	    };
395	  }
396	
397	  const activatedAt = activation.activatedAt ?? new Date().toISOString();
398	  const previous = courseAllocations[currentCourseIndex];
399	  const selected = courseAllocations[selectedIndex];
400	  previous.status = 'completed';
401	  previous.completedAt = previous.completedAt ?? activatedAt;
402	  selected.status = 'active';
403	
404	  const priorHistory = Array.isArray(details.courseActivationHistory)
405	    ? details.courseActivationHistory.filter(
406	        (entry): entry is TrainingPlanCourseActivationHistoryEntry =>
407	          Boolean(
408	            entry &&
409	              typeof entry === 'object' &&
410	              typeof entry.id === 'string' &&
411	              typeof entry.activeAllocationId === 'string',
412	          ),
413	      )
414	    : [];
415	  details.courseAllocations = courseAllocations;
416	  details.currentCourseIndex = selectedIndex;
417	  details.courseActivationHistory = [
418	    ...priorHistory,
419	    {
420	      id: activation.id,
421	      previousAllocationId: previous.id,
422	      previousCourseName: previous.name,
423	      activeAllocationId: selected.id,
424	      activeCourseName: selected.name,
425	      activatedAt,
426	      activatedBy: activation.activatedBy,
427	      reason: 'manual_progression',
428	    },
429	  ];
430	
431	  return {
432	    advanced: true,
433	    reason: null,
434	    previousCourseName: previous.name,
435	    activeCourseName: selected.name,
436	    fundingDetails: details,
437	  };
438	}
