440	export function advanceTrainingPlanAfterCheckride(
441	  fundingDetails: Record<string, unknown> | null | undefined,
442	  checkride: {
443	    id: string;
444	    type?: string | null;
445	    completedAt?: string;
446	  },
447	) {
448	  const details: TrainingPlanFundingDetails = { ...(fundingDetails ?? {}) };
449	  const completedCheckrideIds = Array.isArray(details.completedCheckrideIds)
450	    ? [...details.completedCheckrideIds]
451	    : [];
452	  const courseAllocations = getTrainingPlanCourseAllocations(details).map(
453	    (allocation) => ({ ...allocation }),
454	  );
455	
456	  if (
457	    !checkride.id ||
458	    completedCheckrideIds.includes(checkride.id) ||
459	    courseAllocations.length === 0
460	  ) {
461	    return {
462	      advanced: false,
463	      planCompleted: false,
464	      activeCourseName: null,
465	      fundingDetails: details,
466	    };
467	  }
468	
469	  const requestedIndex = Number(details.currentCourseIndex);
470	  const currentCourseIndex = Number.isInteger(requestedIndex)
471	    ? Math.min(Math.max(requestedIndex, 0), courseAllocations.length - 1)
472	    : Math.max(
473	        0,
474	        courseAllocations.findIndex(
475	          (allocation) => allocation.status === 'active',
476	        ),
477	      );
478	  const current = courseAllocations[currentCourseIndex];
479	  current.status = 'completed';
480	  current.completedAt = checkride.completedAt ?? new Date().toISOString();
481	  current.checkrideHistoryId = checkride.id;
482	  current.checkrideType = checkride.type ?? undefined;
483	  completedCheckrideIds.push(checkride.id);
484	
485	  const nextCourseIndex = currentCourseIndex + 1;
486	  const planCompleted = nextCourseIndex >= courseAllocations.length;
487	  if (!planCompleted) {
488	    courseAllocations[nextCourseIndex].status = 'active';
489	  }
490	
491	  details.courseAllocations = courseAllocations;
492	  details.currentCourseIndex = planCompleted
493	    ? currentCourseIndex
494	    : nextCourseIndex;
495	  details.completedCheckrideIds = completedCheckrideIds;
496	
497	  return {
498	    advanced: true,
499	    planCompleted,
500	    activeCourseName: planCompleted
501	      ? null
502	      : courseAllocations[nextCourseIndex].name,
503	    fundingDetails: details,
504	  };
505	}
