3	export type TrainingPlanAllocationHourBucket =
4	  | 'flight'
5	  | 'ground'
6	  | 'simulator';
7	
8	export interface TrainingPlanAllocationHourTargets {
9	  flightHoursTotal: number;
10	  groundHoursTotal: number;
11	  simulatorHoursTotal: number;
12	}
13	
14	export interface TrainingPlanAllocationHourDeltas {
15	  flight: number;
16	  ground: number;
17	  simulator: number;
18	}
19	
20	export interface TrainingPlanAllocationPricedHourItem {
21	  bucket: string;
22	  hours: number;
23	  rate: number;
24	  amount: number;
25	  groupSourceId?: string | null;
26	}
27	
28	export interface TrainingPlanAllocationAdjustmentImpact<
29	  T extends TrainingPlanAllocationPricedHourItem,
30	> {
31	  hourItems: T[];
32	  matchedLineCount: number;
33	  previousPlanAmount: number;
34	  nextPlanAmount: number;
