84	
85	function money(value: number) {
86	  return Math.round(value * 100) / 100;
87	}
88	
89	function safeNonNegative(value: unknown) {
90	  const number = Number(value);
91	  return Number.isFinite(number) ? Math.max(0, number) : 0;
92	}
93	
94	function hours(value: number) {
95	  // Never allocate more training time than the purchased value can cover.
96	  return Math.floor(value * 10_000) / 10_000;
97	}
98	
99	export function calculateTrainingPlanValueTransfer<
100	  T extends TrainingPlanAllocationPricedHourItem,
101	>(
102	  hourItems: T[],
103	  destinationAllocationId: string,
104	  hourType: TrainingPlanAllocationHourBucket,
105	  transferValueInput: number,
106	): TrainingPlanValueTransferQuote {
107	  const transferValue = money(safeNonNegative(transferValueInput));
108	  const destinationHourlyRate = money(
109	    hourItems
110	      .filter(
111	        (item) =>
112	          item.groupSourceId === destinationAllocationId &&
113	          item.bucket === hourType,
114	      )
115	      .reduce((sum, item) => sum + safeNonNegative(item.rate), 0),
116	  );
117	  const destinationHours =
118	    destinationHourlyRate > 0
119	      ? hours(transferValue / destinationHourlyRate)
120	      : 0;
121	  const destinationValue = money(destinationHours * destinationHourlyRate);
122	
123	  return {
124	    transferValue,
125	    destinationHourlyRate,
126	    destinationHours,
127	    destinationValue,
128	    residualValue: money(transferValue - destinationValue),
129	  };
130	}
131	
132	function getTargetHours(
133	  bucket: string,
134	  targets: TrainingPlanAllocationHourTargets,
135	) {
136	  if (bucket === 'ground') return safeNonNegative(targets.groundHoursTotal);
137	  if (bucket === 'simulator') {
138	    return safeNonNegative(targets.simulatorHoursTotal);
139	  }
140	  return safeNonNegative(targets.flightHoursTotal);
141	}
142	
143	function getDeltaHours(
144	  bucket: string,
145	  deltas: TrainingPlanAllocationHourDeltas,
146	) {
147	  if (bucket === 'ground') return safeNonNegative(deltas.ground);
148	  if (bucket === 'simulator') return safeNonNegative(deltas.simulator);
149	  return safeNonNegative(deltas.flight);
150	}
151	
152	/**
153	 * Reprices every hour line linked to a certificate allocation.
154	 *
155	 * Instruction and equipment lines intentionally receive the same hour total:
156	 * both are charged, while the training-hour total still treats their time as
157	 * concurrent. This matches the training-plan builder's pricing model.
158	 */
159	export function calculateTrainingPlanAllocationAdjustment<
160	  T extends TrainingPlanAllocationPricedHourItem,
161	>(
162	  hourItems: T[],
163	  allocationId: string,
164	  targets: TrainingPlanAllocationHourTargets,
165	): TrainingPlanAllocationAdjustmentImpact<T> {
166	  let matchedLineCount = 0;
167	  const previousPlanAmount = hourItems.reduce(
168	    (sum, item) => sum + safeNonNegative(item.amount),
169	    0,
170	  );
171	  const nextHourItems = hourItems.map((item) => {
172	    if (item.groupSourceId !== allocationId) return { ...item };
173	    matchedLineCount += 1;
174	    const hours = getTargetHours(item.bucket, targets);
175	    const rate = safeNonNegative(item.rate);
176	    return {
177	      ...item,
178	      hours,
179	      amount: money(hours * rate),
180	    };
181	  });
182	  const nextPlanAmount = nextHourItems.reduce(
183	    (sum, item) => sum + safeNonNegative(item.amount),
184	    0,
185	  );
186	  const amountDelta = money(nextPlanAmount - previousPlanAmount);
187	
188	  return {
189	    hourItems: nextHourItems,
190	    matchedLineCount,
191	    previousPlanAmount: money(previousPlanAmount),
192	    nextPlanAmount: money(nextPlanAmount),
193	    amountDelta,
194	    additionalAmount: Math.max(0, amountDelta),
195	  };
196	}
197	
198	/**
199	 * Prices only newly purchased hours while preserving the original quote.
200	 *
201	 * Older plans can contain stored line amounts that intentionally differ from
202	 * `hours × rate`. An overage purchase must add the linked hourly rate to that
203	 * snapshot, not silently reprice all previously quoted hours.
204	 */
205	export function calculateTrainingPlanAllocationPurchase<
206	  T extends TrainingPlanAllocationPricedHourItem,
207	>(
208	  hourItems: T[],
209	  allocationId: string,
210	  deltas: TrainingPlanAllocationHourDeltas,
211	): TrainingPlanAllocationAdjustmentImpact<T> {
212	  let matchedLineCount = 0;
213	  const previousPlanAmount = hourItems.reduce(
214	    (sum, item) => sum + safeNonNegative(item.amount),
215	    0,
216	  );
217	  const nextHourItems = hourItems.map((item) => {
218	    if (item.groupSourceId !== allocationId) return { ...item };
219	    const addedHours = getDeltaHours(item.bucket, deltas);
220	    if (addedHours <= 0) return { ...item };
221	    matchedLineCount += 1;
222	    const rate = safeNonNegative(item.rate);
223	    return {
224	      ...item,
225	      hours: money(safeNonNegative(item.hours) + addedHours),
226	      amount: money(safeNonNegative(item.amount) + addedHours * rate),
227	    };
228	  });
229	  const nextPlanAmount = nextHourItems.reduce(
230	    (sum, item) => sum + safeNonNegative(item.amount),
231	    0,
232	  );
233	  const amountDelta = money(nextPlanAmount - previousPlanAmount);
234	
235	  return {
236	    hourItems: nextHourItems,
237	    matchedLineCount,
238	    previousPlanAmount: money(previousPlanAmount),
239	    nextPlanAmount: money(nextPlanAmount),
240	    amountDelta,
241	    additionalAmount: Math.max(0, amountDelta),
242	  };
243	}
244	
245	/**
246	 * Adds new, catalog-priced hour lines for an overage purchase.
247	 *
248	 * Each selected Location Settings product becomes its own invoice line. New
249	 * lines are appended instead of rewriting the original quote, so a rate change
250	 * in Settings never reprices hours the student already purchased.
251	 */
252	export function calculateTrainingPlanCatalogProductPurchase<
253	  T extends TrainingPlanAllocationPricedHourItem & {
254	    label?: string;
255	    productId?: string | null;
256	    productName?: string | null;
257	    lineItemTypeId?: string | null;
258	    revenueCategory?: string | null;
259	    taxCategory?: string | null;
260	    groupId?: string;
261	    groupName?: string;
262	    groupOrder?: number;
263	    groupSourceKind?: string;
264	    curriculumId?: string | null;
265	    curriculumTitle?: string | null;
266	    category?: string;
267	    productHint?: string;
268	    aircraftEngineType?: string;
269	    source?: string;
270	  },
271	>(
272	  hourItems: T[],
273	  allocationId: string,
274	  addedHoursInput: number,
275	  products: TrainingPlanCatalogPurchaseProduct[],
276	): TrainingPlanAllocationAdjustmentImpact<T> {
277	  const addedHours = safeNonNegative(addedHoursInput);
278	  const selectedProducts = products.filter(
279	    (product) =>
280	      product.id.trim() &&
281	      product.name.trim() &&
282	      safeNonNegative(product.rate) > 0,
283	  );
284	  const previousPlanAmount = hourItems.reduce(
285	    (sum, item) => sum + safeNonNegative(item.amount),
286	    0,
287	  );
288	  const allocationTemplate = hourItems.find(
289	    (item) => item.groupSourceId === allocationId,
290	  );
291	
292	  if (addedHours <= 0 || selectedProducts.length === 0) {
293	    return {
294	      hourItems: hourItems.map((item) => ({ ...item })),
295	      matchedLineCount: 0,
296	      previousPlanAmount: money(previousPlanAmount),
297	      nextPlanAmount: money(previousPlanAmount),
298	      amountDelta: 0,
299	      additionalAmount: 0,
300	    };
301	  }
302	
303	  const purchaseLines = selectedProducts.map((product) => {
304	    const rate = safeNonNegative(product.rate);
305	    return {
306	      bucket: product.bucket,
307	      label: product.name,
308	      hours: money(addedHours),
309	      rate,
310	      amount: money(addedHours * rate),
311	      groupSourceId: allocationId,
312	      groupId: allocationTemplate?.groupId,
313	      groupName: allocationTemplate?.groupName,
314	      groupOrder: allocationTemplate?.groupOrder,
315	      groupSourceKind: allocationTemplate?.groupSourceKind,
316	      curriculumId: allocationTemplate?.curriculumId,
317	      curriculumTitle: allocationTemplate?.curriculumTitle,
318	      productId: product.id,
319	      productName: product.productName?.trim() || product.name,
320	      lineItemTypeId: product.lineItemTypeId?.trim() || product.id,
321	      revenueCategory: product.revenueCategory ?? null,
322	      taxCategory: product.taxCategory ?? null,
323	      category: product.category,
324	      productHint: product.productHint,
325	      aircraftEngineType: product.aircraftEngineType,
326	      source: TRAINING_PLAN_ALLOCATION_PURCHASE_SOURCE,
327	    } as T;
328	  });
329	  const nextHourItems = [
330	    ...hourItems.map((item) => ({ ...item })),
331	    ...purchaseLines,
332	  ];
333	  const additionalAmount = money(
334	    purchaseLines.reduce((sum, item) => sum + safeNonNegative(item.amount), 0),
335	  );
336	  const nextPlanAmount = money(previousPlanAmount + additionalAmount);
337	
338	  return {
339	    hourItems: nextHourItems,
340	    matchedLineCount: purchaseLines.length,
341	    previousPlanAmount: money(previousPlanAmount),
342	    nextPlanAmount,
343	    amountDelta: additionalAmount,
344	    additionalAmount,
345	  };
346	}
