348	/**
349	 * Reprices both sides of a same-plan allocation transfer in one calculation.
350	 * A transfer is deliberately not assumed to be dollar-neutral because the
351	 * source and destination certificates can use different instruction or
352	 * equipment rates.
353	 */
354	export function calculateTrainingPlanAllocationTransfer<
355	  T extends TrainingPlanAllocationPricedHourItem,
356	>(
357	  hourItems: T[],
358	  sourceAllocationId: string,
359	  sourceTargets: TrainingPlanAllocationHourTargets,
360	  destinationAllocationId: string,
361	  destinationTargets: TrainingPlanAllocationHourTargets,
362	): TrainingPlanAllocationTransferImpact<T> {
363	  const sourceImpact = calculateTrainingPlanAllocationAdjustment(
364	    hourItems,
365	    sourceAllocationId,
366	    sourceTargets,
367	  );
368	  const destinationImpact = calculateTrainingPlanAllocationAdjustment(
369	    sourceImpact.hourItems,
370	    destinationAllocationId,
371	    destinationTargets,
372	  );
373	
374	  return {
375	    hourItems: destinationImpact.hourItems,
376	    sourceImpact,
377	    destinationImpact,
378	    previousPlanAmount: sourceImpact.previousPlanAmount,
379	    nextPlanAmount: destinationImpact.nextPlanAmount,
380	    amountDelta: money(
381	      destinationImpact.nextPlanAmount - sourceImpact.previousPlanAmount,
382	    ),
383	  };
384	}
