45	function toCents(value: unknown) {
46	  const amount = Number(value);
47	  return Number.isFinite(amount) ? Math.round(amount * 100) : 0;
48	}
49	
50	function fromCents(value: number) {
51	  return Math.round(value) / 100;
52	}
53	
54	function normalizeLabel(value: unknown) {
55	  return String(value ?? '')
56	    .trim()
57	    .toLowerCase()
58	    .replace(/[^a-z0-9]+/g, ' ')
59	    .trim();
60	}
61	
62	function getFeeBillingMultiplier(item: TrainingPlanCertificateCostFeeItem) {
63	  if (item.timing !== 'Monthly subscription') return 1;
64	  const months = Number(item.billingMonths);
65	  if (!Number.isFinite(months)) return 1;
66	  return Math.min(120, Math.max(1, Math.trunc(months)));
67	}
