69	export function buildTrainingPlanCertificateCosts(
70	  courses: TrainingPlanCertificateCostCourse[],
71	  hourItems: TrainingPlanCertificateCostHourItem[],
72	  feeItems: TrainingPlanCertificateCostFeeItem[],
73	): TrainingPlanCertificateCostPlan {
74	  const certificateCents = new Map<string, { training: number; fees: number }>(
75	    courses.map((course) => [
76	      course.id,
77	      {
78	        training: 0,
79	        fees: 0,
80	      },
81	    ]),
82	  );
83	  const courseByNormalizedName = new Map(
84	    courses.map((course) => [normalizeLabel(course.name), course]),
85	  );
86	  let unallocatedTrainingCents = 0;
87	  let unallocatedFeeCents = 0;
88	  let programFeeCents = 0;
89	
90	  for (const item of hourItems) {
91	    const amountCents = Math.max(0, toCents(item.amount));
92	    const matchedCourse =
93	      courses.find((course) => course.id === item.groupSourceId) ??
94	      courseByNormalizedName.get(normalizeLabel(item.groupName)) ??
95	      (courses.length === 1 ? courses[0] : undefined);
96	    if (!matchedCourse) {
97	      unallocatedTrainingCents += amountCents;
98	      continue;
99	    }
100	    const amounts = certificateCents.get(matchedCourse.id);
101	    if (amounts) amounts.training += amountCents;
102	  }
103	
104	  for (const item of feeItems) {
105	    const billingMultiplier = getFeeBillingMultiplier(item);
106	    const itemAmountCents =
107	      Math.max(0, toCents(item.amount)) * billingMultiplier;
108	    const definitions = Array.isArray(item.definitions) ? item.definitions : [];
109	
110	    // Recurring subscriptions (for example, living expenses) belong to the
111	    // overall student program rather than a specific certificate. Ignore any
112	    // legacy definition rows so they cannot create a false allocation error.
113	    if (item.timing === 'Monthly subscription') {
114	      programFeeCents += itemAmountCents;
115	      continue;
116	    }
117	
118	    if (definitions.length === 0) {
119	      if (courses.length === 1) {
120	        const amounts = certificateCents.get(courses[0].id);
121	        if (amounts) amounts.fees += itemAmountCents;
122	      } else {
123	        unallocatedFeeCents += itemAmountCents;
124	      }
125	      continue;
126	    }
127	
128	    let definitionTotalCents = 0;
129	    for (const definition of definitions) {
130	      const amountCents =
131	        Math.max(0, toCents(definition.amount)) * billingMultiplier;
132	      definitionTotalCents += amountCents;
133	      const matchedCourse =
134	        courses.find(
135	          (course) => course.id === definition.certificateRatingId,
136	        ) ?? (courses.length === 1 ? courses[0] : undefined);
137	      if (!matchedCourse) {
138	        unallocatedFeeCents += amountCents;
139	        continue;
140	      }
141	      const amounts = certificateCents.get(matchedCourse.id);
142	      if (amounts) amounts.fees += amountCents;
143	    }
144	
145	    if (itemAmountCents > definitionTotalCents) {
146	      unallocatedFeeCents += itemAmountCents - definitionTotalCents;
147	    }
148	  }
149	
150	  const certificates = courses.map((course) => {
151	    const amounts = certificateCents.get(course.id) ?? {
152	      training: 0,
153	      fees: 0,
154	    };
155	    return {
156	      certificateId: course.id,
157	      certificateName: course.name,
158	      certificateCode: course.code ?? null,
159	      trainingAmount: fromCents(amounts.training),
160	      feeAmount: fromCents(amounts.fees),
161	      totalAmount: fromCents(amounts.training + amounts.fees),
162	    };
163	  });
164	  const allocatedTrainingCents = certificates.reduce(
165	    (sum, certificate) => sum + toCents(certificate.trainingAmount),
166	    0,
167	  );
168	  const allocatedFeeCents = certificates.reduce(
169	    (sum, certificate) => sum + toCents(certificate.feeAmount),
170	    0,
171	  );
172	  const allocatedTotalCents = allocatedTrainingCents + allocatedFeeCents;
173	
174	  return {
175	    certificates,
176	    allocatedTrainingAmount: fromCents(allocatedTrainingCents),
177	    allocatedFeeAmount: fromCents(allocatedFeeCents),
178	    programFeeAmount: fromCents(programFeeCents),
179	    unallocatedTrainingAmount: fromCents(unallocatedTrainingCents),
180	    unallocatedFeeAmount: fromCents(unallocatedFeeCents),
181	    allocatedTotal: fromCents(allocatedTotalCents),
182	    plannedTotal: fromCents(
183	      allocatedTotalCents +
184	        programFeeCents +
185	        unallocatedTrainingCents +
186	        unallocatedFeeCents,
187	    ),
188	  };
189	}
