1	const DAY_MS = 24 * 60 * 60 * 1000;
2	const WEEK_DAYS = 7;
3	const DATE_ONLY_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
4	
5	function parseDateOnly(value: string | null | undefined) {
6	  if (!value || !DATE_ONLY_PATTERN.test(value)) return null;
7	  const date = new Date(`${value}T00:00:00.000Z`);
8	  if (Number.isNaN(date.getTime())) return null;
9	  return date.toISOString().slice(0, 10) === value ? date : null;
10	}
11	
12	export function calculateCourseScheduleDurationWeeks(
13	  startDate: string | null | undefined,
14	  endDate: string | null | undefined,
15	) {
16	  const start = parseDateOnly(startDate);
17	  const end = parseDateOnly(endDate);
18	  if (!start || !end || end.getTime() < start.getTime()) return null;
19	
20	  const inclusiveDays =
21	    Math.floor((end.getTime() - start.getTime()) / DAY_MS) + 1;
22	  return Math.max(1, Math.ceil(inclusiveDays / WEEK_DAYS));
23	}
24	
25	export function calculateCourseScheduleEpw(
26	  totalEvents: number | null | undefined,
27	  startDate: string | null | undefined,
28	  endDate: string | null | undefined,
29	) {
30	  const events = Number(totalEvents);
31	  const weeks = calculateCourseScheduleDurationWeeks(startDate, endDate);
32	  if (!Number.isFinite(events) || events <= 0 || !weeks) return null;
33	
34	  return Math.round((events / weeks) * 10) / 10;
35	}
36	
37	export function calculateCourseScheduleEndDate(
38	  startDate: string | null | undefined,
39	  durationWeeks: number | null | undefined,
40	) {
41	  const start = parseDateOnly(startDate);
42	  const weeks = Math.ceil(Number(durationWeeks));
43	  if (!start || !Number.isFinite(weeks) || weeks <= 0) return '';
44	
45	  const end = new Date(start);
46	  end.setUTCDate(end.getUTCDate() + weeks * WEEK_DAYS - 1);
47	  return end.toISOString().slice(0, 10);
48	}
49	
50	export function calculateNextCourseScheduleStartDate(
51	  endDate: string | null | undefined,
52	) {
53	  const end = parseDateOnly(endDate);
54	  if (!end) return '';
55	
56	  const start = new Date(end);
57	  start.setUTCDate(start.getUTCDate() + 1);
58	  return start.toISOString().slice(0, 10);
59	}
60	
61	export function isValidCourseScheduleWindow(
62	  startDate: string | null | undefined,
63	  endDate: string | null | undefined,
64	) {
65	  if (!startDate || !endDate) return true;
66	  return calculateCourseScheduleDurationWeeks(startDate, endDate) !== null;
67	}
