69	export type CourseScheduleStatus =
70	  | 'unscheduled'
71	  | 'upcoming'
72	  | 'scheduled'
73	  | 'past_target'
74	  | 'completed'
75	  | 'completed_late';
76	
77	function getLocalDateOnly(date = new Date()) {
78	  const year = date.getFullYear();
79	  const month = String(date.getMonth() + 1).padStart(2, '0');
80	  const day = String(date.getDate()).padStart(2, '0');
81	  return `${year}-${month}-${day}`;
82	}
83	
84	export function getCourseScheduleStatus(input: {
85	  startDate?: string | null;
86	  endDate?: string | null;
87	  completedAt?: string | null;
88	  today?: string;
89	}): CourseScheduleStatus {
90	  const startDate = parseDateOnly(input.startDate)
91	    ? String(input.startDate)
92	    : '';
93	  const endDate = parseDateOnly(input.endDate) ? String(input.endDate) : '';
94	  const completedDate = String(input.completedAt ?? '').slice(0, 10);
95	
96	  if (completedDate) {
97	    return endDate && completedDate > endDate ? 'completed_late' : 'completed';
98	  }
99	  if (!startDate && !endDate) return 'unscheduled';
100	
101	  const today = parseDateOnly(input.today)
102	    ? String(input.today)
103	    : getLocalDateOnly();
104	  if (startDate && today < startDate) return 'upcoming';
105	  if (endDate && today > endDate) return 'past_target';
106	  return 'scheduled';
107	}
