61	type CertificateSummary = {
62	  id: string;
63	  name: string;
64	  totalAmount?: number | null;
65	};
66	
67	function toCents(value: number) {
68	  return Math.round((Number(value) || 0) * 100);
69	}
70	
71	function fromCents(value: number) {
72	  return Math.round(value) / 100;
73	}
74	
75	function toBasisPoints(value: number) {
76	  return Math.round((Number(value) || 0) * 100);
77	}
78	
79	function getMilestoneAmountCents(
80	  milestone: LenderFundingMilestone,
81	  authorizedCents: number,
82	  releaseMode: LenderFundingReleaseMode,
83	) {
84	  if (releaseMode === 'percentage') {
85	    return Math.max(
86	      0,
87	      Math.round(
88	        (authorizedCents * toBasisPoints(milestone.percentage ?? 0)) / 10_000,
89	      ),
90	    );
91	  }
92	  return Math.max(0, toCents(milestone.amount));
93	}
94	
95	export function buildCertificateLenderMilestones(
96	  certificates: CertificateSummary[],
97	  authorizedAmount: number,
98	): LenderFundingMilestone[] {
99	  if (certificates.length === 0) return [];
100	
101	  const calculatedCostCents = certificates.map((certificate) =>
102	    Math.max(0, toCents(certificate.totalAmount ?? 0)),
103	  );
104	  const calculatedTotalCents = calculatedCostCents.reduce(
105	    (sum, amount) => sum + amount,
106	    0,
107	  );
108	  const totalCents =
109	    Math.max(0, toCents(authorizedAmount)) || calculatedTotalCents;
110	  const useCalculatedCosts = calculatedTotalCents > 0;
111	  const baseCents = Math.floor(totalCents / certificates.length);
112	  let assignedCents = 0;
113	  let assignedBasisPoints = 0;
114	
115	  return certificates.map((certificate, index) => {
116	    const amountCents =
117	      index === certificates.length - 1
118	        ? totalCents - assignedCents
119	        : useCalculatedCosts
120	          ? Math.floor(
121	              (totalCents * calculatedCostCents[index]) / calculatedTotalCents,
122	            )
123	          : baseCents;
124	    assignedCents += amountCents;
125	    const percentageBasisPoints =
126	      index === certificates.length - 1
127	        ? 10_000 - assignedBasisPoints
128	        : totalCents > 0
129	          ? Math.round((amountCents / totalCents) * 10_000)
130	          : 0;
131	    assignedBasisPoints += percentageBasisPoints;
132	    return {
133	      id: `lender-certificate-${certificate.id}`,
134	      certificateId: certificate.id,
135	      certificateName: certificate.name,
136	      amount: fromCents(amountCents),
137	      percentage: percentageBasisPoints / 100,
138	    };
139	  });
140	}
