142	export function validateCertificateLenderMilestoneCosts(
143	  schedule: LenderFundingSchedule,
144	  authorizedAmount: number,
145	  certificates: CertificateSummary[],
146	) {
147	  if (schedule.basis !== 'certificate') return null;
148	
149	  const expectedMilestones = buildCertificateLenderMilestones(
150	    certificates,
151	    authorizedAmount,
152	  );
153	  const actualMilestones = new Map(
154	    schedule.milestones.map((milestone) => [
155	      milestone.certificateId,
156	      milestone,
157	    ]),
158	  );
159	  const hasMismatch = expectedMilestones.some((expected) => {
160	    const actual = actualMilestones.get(expected.certificateId);
161	    if (!actual) return true;
162	    return schedule.releaseMode === 'percentage'
163	      ? Math.abs(Number(actual.percentage) - Number(expected.percentage)) >
164	          0.0001
165	      : Math.abs(Number(actual.amount) - Number(expected.amount)) > 0.009;
166	  });
167	
168	  return hasMismatch
169	    ? 'Certificate releases must match the calculated cost of each certificate'
170	    : null;
171	}
