173	export function normalizeLenderFundingSchedule(
174	  value: unknown,
175	): LenderFundingSchedule | null {
176	  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
177	  const record = value as Record<string, unknown>;
178	  const basis = record.basis;
179	  if (
180	    basis !== 'certificate' &&
181	    basis !== 'training_hours' &&
182	    basis !== 'flight_hours' &&
183	    basis !== 'simulator_hours'
184	  ) {
185	    return null;
186	  }
187	  const normalizedBasis: LenderFundingMilestoneBasis =
188	    basis === 'certificate' ? 'certificate' : 'training_hours';
189	  const releaseMode: LenderFundingReleaseMode =
190	    record.releaseMode === 'percentage' ? 'percentage' : 'amount';
191	  const certificateReleaseEvent = record.certificateReleaseEvent;
192	  if (
193	    certificateReleaseEvent !== 'certificate_start' &&
194	    certificateReleaseEvent !== 'checkride_complete'
195	  ) {
196	    return null;
197	  }
198	  if (!Array.isArray(record.milestones)) return null;
199	
200	  const milestones = record.milestones
201	    .filter((milestone): milestone is Record<string, unknown> =>
202	      Boolean(
203	        milestone && typeof milestone === 'object' && !Array.isArray(milestone),
204	      ),
205	    )
206	    .map((milestone, index) => ({
207	      id:
208	        typeof milestone.id === 'string'
209	          ? milestone.id
210	          : `lender-milestone-${index + 1}`,
211	      amount: Number(milestone.amount) || 0,
212	      percentage: Number.isFinite(Number(milestone.percentage))
213	        ? Number(milestone.percentage)
214	        : null,
215	      certificateId:
216	        typeof milestone.certificateId === 'string'
217	          ? milestone.certificateId
218	          : null,
219	      certificateName:
220	        typeof milestone.certificateName === 'string'
221	          ? milestone.certificateName
222	          : null,
223	      thresholdHours: Number.isFinite(Number(milestone.thresholdHours))
224	        ? Number(milestone.thresholdHours)
225	        : null,
226	    }));
227	
228	  return {
229	    basis: normalizedBasis,
230	    releaseMode,
231	    certificateReleaseEvent,
232	    milestones,
233	  };
234	}
