236	export function validateLenderFundingSchedule(
237	  schedule: LenderFundingSchedule,
238	  authorizedAmount: number,
239	  certificates: CertificateSummary[],
240	  hourLimits?: { flight?: number; simulator?: number; training?: number },
241	): LenderFundingValidationResult {
242	  const authorizedCents = toCents(authorizedAmount);
243	  const releaseMode = schedule.releaseMode ?? 'amount';
244	  const scheduledCents = schedule.milestones.reduce(
245	    (sum, milestone) =>
246	      sum + getMilestoneAmountCents(milestone, authorizedCents, releaseMode),
247	    0,
248	  );
249	  const result = (error: string | null): LenderFundingValidationResult => ({
250	    isValid: error === null,
251	    scheduledAmount: fromCents(scheduledCents),
252	    remainingAmount: fromCents(authorizedCents - scheduledCents),
253	    error,
254	  });
255	
256	  if (authorizedCents <= 0) {
257	    return result('Enter the lender-authorized amount.');
258	  }
259	  if (schedule.milestones.length === 0) {
260	    return result('Add at least one lender release milestone.');
261	  }
262	  if (
263	    releaseMode === 'percentage' &&
264	    schedule.milestones.some(
265	      (milestone) => toBasisPoints(milestone.percentage ?? 0) <= 0,
266	    )
267	  ) {
268	    return result(
269	      'Every lender release must have a percentage greater than 0%.',
270	    );
271	  }
272	  if (
273	    releaseMode === 'amount' &&
274	    schedule.milestones.some((milestone) => toCents(milestone.amount) <= 0)
275	  ) {
276	    return result('Every lender release must have an amount greater than $0.');
277	  }
278	
279	  if (schedule.basis === 'certificate') {
280	    const expectedIds = certificates.map((certificate) => certificate.id);
281	    const actualIds = schedule.milestones.map(
282	      (milestone) => milestone.certificateId,
283	    );
284	    if (
285	      actualIds.length !== expectedIds.length ||
286	      new Set(actualIds).size !== actualIds.length ||
287	      expectedIds.some((id) => !actualIds.includes(id))
288	    ) {
289	      return result(
290	        'Define one lender release for every certificate in the plan.',
291	      );
292	    }
293	  } else {
294	    const thresholdLabel = 'training-hour';
295	    const hourLimit =
296	      hourLimits?.training ??
297	      ((hourLimits?.flight ?? 0) + (hourLimits?.simulator ?? 0) || undefined);
298	    let previousThreshold = 0;
299	    for (const milestone of schedule.milestones) {
300	      const threshold = Number(milestone.thresholdHours) || 0;
301	      if (threshold <= 0) {
302	        return result(
303	          `Every ${thresholdLabel} milestone must be greater than 0.`,
304	        );
305	      }
306	      if (threshold <= previousThreshold) {
307	        return result(
308	          `${thresholdLabel[0].toUpperCase()}${thresholdLabel.slice(1)} milestones must be in ascending order.`,
309	        );
310	      }
311	      if (hourLimit !== undefined && threshold > hourLimit) {
312	        return result(
313	          `${thresholdLabel[0].toUpperCase()}${thresholdLabel.slice(1)} milestones cannot exceed the plan's ${hourLimit.toFixed(1)} allotted hours.`,
314	        );
315	      }
316	      previousThreshold = threshold;
317	    }
318	  }
319	
320	  if (
321	    releaseMode === 'percentage' &&
322	    schedule.milestones.reduce(
323	      (sum, milestone) => sum + toBasisPoints(milestone.percentage ?? 0),
324	      0,
325	    ) !== 10_000
326	  ) {
327	    return result('Lender release percentages must total 100%.');
328	  }
329	
330	  if (scheduledCents !== authorizedCents) {
331	    return result('Lender releases must total the authorized amount.');
332	  }
333	  return result(null);
334	}
