9	function asRecord(value: unknown): UnknownRecord | null {
10	  return value && typeof value === 'object' && !Array.isArray(value)
11	    ? (value as UnknownRecord)
12	    : null;
13	}
14	
15	function asInstallments(schedule: UnknownRecord | null) {
16	  return Array.isArray(schedule?.installments)
17	    ? schedule.installments
18	        .map(asRecord)
19	        .filter((item): item is UnknownRecord => Boolean(item))
20	    : [];
21	}
22	
23	function normalizedText(value: unknown) {
24	  return typeof value === 'string' ? value.trim() : '';
25	}
26	
27	function normalizedNumber(value: unknown) {
28	  const parsed = Number(value);
29	  return Number.isFinite(parsed) ? parsed : 0;
30	}
31	
32	function sameMoney(left: unknown, right: unknown) {
33	  return (
34	    Math.round(normalizedNumber(left) * 100) ===
35	    Math.round(normalizedNumber(right) * 100)
36	  );
37	}
38	
39	function sameScheduleValue(left: unknown, right: unknown) {
40	  return (
41	    Math.round(normalizedNumber(left) * 10_000) ===
42	    Math.round(normalizedNumber(right) * 10_000)
43	  );
44	}
45	
46	function installmentValue(installment: UnknownRecord, mode: string): unknown {
47	  if ('value' in installment) return installment.value;
48	  return mode === 'percentage' ? installment.percentage : installment.amount;
49	}
