51	/**
52	 * Any installment with non-failed transaction history is protected. This
53	 * includes completed, refunded, pending, and processing records so an edit
54	 * cannot sever an accounting or payment-provider reference.
55	 */
56	export function getProtectedTrainingPlanInstallmentIds(
57	  payments: TrainingPlanLinkedPayment[],
58	  balanceId: string,
59	) {
60	  return new Set(
61	    payments.flatMap((payment) => {
62	      const installmentId = normalizedText(payment.trainingPlanInstallmentId);
63	      if (
64	        payment.trainingPlanBalanceId !== balanceId ||
65	        !installmentId ||
66	        normalizedText(payment.status).toLowerCase() === 'failed'
67	      ) {
68	        return [];
69	      }
70	      return [installmentId];
71	    }),
72	  );
73	}
