75	/**
76	 * Protects the stable identity and accounting terms of installments that
77	 * already have payment activity. Open installments remain fully editable.
78	 */
79	export function validateProtectedTrainingPlanInstallmentEdit(input: {
80	  currentSchedule: unknown;
81	  nextSchedule: unknown;
82	  protectedInstallmentIds: Iterable<string>;
83	}) {
84	  const protectedIds = new Set(input.protectedInstallmentIds);
85	  if (protectedIds.size === 0) return null;
86	
87	  const currentSchedule = asRecord(input.currentSchedule);
88	  const nextSchedule = asRecord(input.nextSchedule);
89	  if (!currentSchedule || !nextSchedule) {
90	    return 'The payment schedule cannot be removed after payment activity has started.';
91	  }
92	
93	  if (
94	    normalizedText(currentSchedule.mode) !== normalizedText(nextSchedule.mode)
95	  ) {
96	    return 'The payment schedule type cannot change after payment activity has started.';
97	  }
98	
99	  const currentInstallments = asInstallments(currentSchedule);
100	  const nextInstallments = asInstallments(nextSchedule);
101	  const scheduleMode = normalizedText(currentSchedule.mode);
102	  const nextById = new Map(
103	    nextInstallments.map((installment) => [
104	      normalizedText(installment.id),
105	      installment,
106	    ]),
107	  );
108	
109	  for (const protectedId of protectedIds) {
110	    const currentIndex = currentInstallments.findIndex(
111	      (installment) => normalizedText(installment.id) === protectedId,
112	    );
113	    const current = currentInstallments[currentIndex];
114	    const next = nextById.get(protectedId);
115	    if (!current || !next) {
116	      return 'Payments with transaction history cannot be removed from the schedule.';
117	    }
118	
119	    const nextIndex = nextInstallments.findIndex(
120	      (installment) => normalizedText(installment.id) === protectedId,
121	    );
122	    if (
123	      currentIndex !== nextIndex ||
124	      (normalizedNumber(current.sequence) || currentIndex + 1) !==
125	        (normalizedNumber(next.sequence) || nextIndex + 1)
126	    ) {
127	      return 'Payments with transaction history must keep their original schedule position.';
128	    }
129	    if (
130	      normalizedText(current.dueDate) !== normalizedText(next.dueDate) ||
131	      !sameScheduleValue(
132	        installmentValue(current, scheduleMode),
133	        installmentValue(next, scheduleMode),
134	      ) ||
135	      ('amount' in current && !sameMoney(current.amount, next.amount))
136	    ) {
137	      return 'Completed or processing payments cannot be changed. Edit only open installments.';
138	    }
139	  }
140	
141	  return null;
142	}
