81	function paymentSourceLabel(details: UnknownRecord, sourceType: string) {
82	  const explicit = String(details.paymentMethodLabel ?? '').trim();
83	  if (explicit) return explicit;
84	  if (sourceType === 'vendor') {
85	    return (
