96	function getStatus(
97	  dueDate: string | null,
98	  amount: number,
99	  paidAmount: number,
100	  processingAmount: number,
101	): TrainingPlanScheduleStatus {
102	  const remaining = Math.max(0, money(amount - paidAmount - processingAmount));
103	  if (remaining <= 0 && processingAmount <= 0) return 'paid';
104	  if (processingAmount > 0) return 'processing';
105	  if (paidAmount > 0) return 'partial';
106	  if (!dueDate) return 'scheduled';
107	  const today = new Date();
108	  const todayValue = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
109	  if (dueDate < todayValue) return 'overdue';
110	  if (dueDate === todayValue) return 'due';
111	  return 'scheduled';
112	}
