114	function linkedAmounts(
115	  balanceId: string,
116	  installmentId: string,
117	  payments: SchedulePayment[],
118	) {
119	  return payments.reduce(
120	    (total, payment) => {
121	      if (
122	        payment.trainingPlanBalanceId !== balanceId ||
123	        payment.trainingPlanInstallmentId !== installmentId ||
124	        payment.status === 'failed'
125	      ) {
126	        return total;
127	      }
128	      if (payment.status === 'processing' || payment.status === 'pending') {
129	        total.processing += Math.max(0, Number(payment.amount) || 0);
130	        return total;
131	      }
132	      if (payment.status !== 'completed') return total;
133	      const signedAmount =
134	        payment.balanceDelta != null
135	          ? Number(payment.balanceDelta) / 100
136	          : payment.type === 'refund'
137	            ? -(Number(payment.amount) || 0)
138	            : Number(payment.amount) || 0;
139	      total.paid += signedAmount;
140	      return total;
141	    },
142	    { paid: 0, processing: 0 },
143	  );
144	}
