146	export function buildTrainingPlanPaymentScheduleViews(
147	  balances: ScheduleBalance[],
148	  payments: SchedulePayment[],
149	): TrainingPlanPaymentScheduleView[] {
150	  return balances.flatMap((balance) => {
151	    if (!balance.id) return [];
152	    const details = asRecord(balance.fundingDetails) ?? {};
153	    const fundingModel = String(balance.fundingModel ?? 'unspecified');
154	    const sourceType = String(
155	      details.paymentSourceType ??
156	        (fundingModel === 'lender' ? 'vendor' : 'student'),
157	    );
158	    const sourceId =
159	      sourceType === 'stripe'
160	        ? String(details.paymentMethodId ?? '') || null
161	        : sourceType === 'vendor'
162	          ? String(details.paymentVendorId ?? details.lenderId ?? '') || null
163	          : null;
164	    const isPayAsYouGo = fundingModel === 'pay_as_you_go';
165	    const paymentSchedule = asRecord(details.paymentSchedule);
166	    const lenderSchedule = asRecord(details.lenderFundingSchedule);
167	    const quotePortal = asRecord(details.quotePortal);
168	    const quoteDeliveries = asRecordArray(quotePortal?.deliveries);
169	    const standardInstallments = asRecordArray(paymentSchedule?.installments);
170	    const lenderMilestones = asRecordArray(lenderSchedule?.milestones);
171	
172	    if (
173	      fundingModel === 'unspecified' &&
174	      !isPayAsYouGo &&
175	      standardInstallments.length === 0 &&
176	      lenderMilestones.length === 0
177	    ) {
178	      return [];
179	    }
180	
181	    const authorizedAmount = money(details.authorizedAmount);
182	    const scheduleTotal = money(
183	      paymentSchedule?.total ??
184	        (fundingModel === 'lender' ? authorizedAmount : 0),
185	    );
186	    const rawItems =
187	      fundingModel === 'lender' ? lenderMilestones : standardInstallments;
188	    const installments = rawItems.map((item, index) => {
189	      const id = String(item.id ?? `${balance.id}-payment-${index + 1}`);
190	      const percentage = Number.isFinite(Number(item.percentage))
191	        ? Number(item.percentage)
192	        : null;
193	      const amount =
194	        fundingModel === 'lender' &&
195	        lenderSchedule?.releaseMode === 'percentage'
196	          ? money(authorizedAmount * ((percentage ?? 0) / 100))
197	          : money(item.amount);
198	      const linked = linkedAmounts(balance.id, id, payments);
199	      const paidAmount = Math.max(0, money(linked.paid));
200	      const processingAmount = Math.max(0, money(linked.processing));
201	      const remainingAmount = Math.max(
202	        0,
203	        money(amount - paidAmount - processingAmount),
204	      );
205	      const dueDate =
206	        typeof item.dueDate === 'string' && item.dueDate ? item.dueDate : null;
207	      const triggerLabel =
208	        fundingModel !== 'lender'
209	          ? null
210	          : typeof item.certificateName === 'string' && item.certificateName
211	            ? `${item.certificateName} ${
212	                lenderSchedule?.certificateReleaseEvent === 'checkride_complete'
213	                  ? 'completion'
214	                  : 'start'
215	              }`
216	            : Number(item.thresholdHours) > 0
217	              ? `${Number(item.thresholdHours).toFixed(1)} training hrs`
218	              : null;
219	      return {
220	        id,
221	        sequence: Number(item.sequence) || index + 1,
222	        label:
223	          fundingModel === 'lender'
224	            ? `Release ${index + 1}`
225	            : `Payment ${Number(item.sequence) || index + 1}`,
226	        dueDate,
227	        triggerLabel,
228	        amount,
229	        paidAmount,
230	        processingAmount,
231	        remainingAmount,
232	        percentage,
233	        status: getStatus(dueDate, amount, paidAmount, processingAmount),
234	      } satisfies TrainingPlanScheduleInstallmentView;
235	    });
236	    const total =
237	      scheduleTotal ||
238	      money(installments.reduce((sum, item) => sum + item.amount, 0));
239	    const paidTotal = money(
240	      installments.reduce((sum, item) => sum + item.paidAmount, 0),
241	    );
242	    const processingTotal = money(
243	      installments.reduce((sum, item) => sum + item.processingAmount, 0),
244	    );
245	    const remainingTotal = Math.max(
246	      0,
247	      money(total - paidTotal - processingTotal),
248	    );
249	    const nextInstallment =
250	      installments.find((item) => item.remainingAmount > 0) ??
251	      installments.find((item) => item.processingAmount > 0) ??
252	      null;
253	    const paymentStructureLabel = isPayAsYouGo
254	      ? 'Pay as you go'
255	      : fundingModel === 'lender'
256	        ? lenderSchedule?.basis === 'training_hours'
257	          ? 'Training-hour releases'
258	          : 'Certificate releases'
259	        : paymentSchedule?.mode === 'percentage'
260	          ? 'Percentage installments'
261	          : 'Fixed amount installments';
262	
263	    return [
264	      {
265	        balanceId: balance.id,
266	        planName:
267	          balance.programName ||
268	          balance.trainingPlanTemplate ||
269	          balance.courseName ||
270	          'Training plan',
271	        fundingModel,
272	        sourceType,
273	        sourceId,
274	        sourceLabel: paymentSourceLabel(details, sourceType),
275	        paymentStructureLabel,
276	        total,
277	        paidTotal,
278	        processingTotal,
279	        remainingTotal,
280	        isPayAsYouGo,
281	        installments,
282	        nextInstallment,
283	        quotePortal: {
284	          lastSentAt:
285	            typeof quotePortal?.lastSentAt === 'string'
286	              ? quotePortal.lastSentAt
287	              : null,
288	          lastSentChannel:
289	            typeof quotePortal?.lastSentChannel === 'string'
290	              ? quotePortal.lastSentChannel
291	              : null,
292	          deliveryCount: quoteDeliveries.length,
293	        },
294	      },
295	    ];
296	  });
297	}
