61	function text(value: unknown) {
62	  return typeof value === 'string' ? value.trim() : '';
63	}
64	
65	function number(value: unknown) {
66	  const parsed = Number(value);
67	  return Number.isFinite(parsed) ? parsed : 0;
68	}
