112	function selectedCourses(fundingDetails: JsonRecord) {
113	  return asRecords(fundingDetails.selectedTrainingCourses).map(
114	    (course, index) => ({
115	      id: text(course.id) || `certificate-${index + 1}`,
116	      name: text(course.name) || `Certificate ${index + 1}`,
117	      code: text(course.code) || null,
118	    }),
