127	function itemMatchesCourse(
128	  item: JsonRecord,
129	  course: { id: string; name: string },
130	) {
131	  const sourceId = text(item.groupSourceId);
132	  if (sourceId && sourceId === course.id) return true;
133	  return normalizeLabel(item.groupName) === normalizeLabel(course.name);
134	}
135	
136	function getCertificateHours(
137	  hourItems: JsonRecord[],
138	  course: { id: string; name: string },
139	) {
140	  const matching = hourItems.filter((item) => itemMatchesCourse(item, course));
141	  const sumBucket = (bucket: 'flight' | 'ground' | 'simulator') => {
142	    const bucketItems = matching.filter((item) => item.bucket === bucket);
143	    const instructionHours = bucketItems
144	      .filter((item) => item.category !== 'aircraft')
145	      .reduce((sum, item) => sum + Math.max(0, number(item.hours)), 0);
146	    const equipmentHours = bucketItems
147	      .filter((item) => item.category === 'aircraft')
148	      .reduce((sum, item) => sum + Math.max(0, number(item.hours)), 0);
149	    return Math.max(instructionHours, equipmentHours);
150	  };
151	  return {
152	    flightHours: sumBucket('flight'),
153	    groundHours: sumBucket('ground'),
154	    simulatorHours: sumBucket('simulator'),
155	  };
156	}
