158	function buildCertificates(
159	  balance: TrainingPlanQuoteBalanceInput,
160	  fundingDetails: JsonRecord,
161	  trainingTotal: number,
162	  feeTotal: number,
163	): TrainingPlanQuoteCertificate[] {
164	  const courses = selectedCourses(fundingDetails);
165	  const hourItems = asRecords(balance.hourItems);
166	  const snapshots = certificateSnapshot(fundingDetails);
167	  if (courses.length === 0) {
168	    return [
169	      {
170	        name: planName(balance),
171	        code: null,
172	        flightHours: number(balance.flightHoursTotal),
173	        groundHours: number(balance.groundHoursTotal),
174	        simulatorHours: number(balance.simulatorHoursTotal),
175	        trainingAmount: trainingTotal,
176	        feeAmount: feeTotal,
177	        totalAmount: trainingTotal + feeTotal,
178	      },
179	    ];
180	  }
181	
182	  return courses.map((course) => {
183	    const snapshot =
184	      snapshots.find((item) => text(item.certificateId) === course.id) ??
185	      snapshots.find(
186	        (item) =>
187	          normalizeLabel(item.certificateName) === normalizeLabel(course.name),
188	      );
189	    const hours = getCertificateHours(hourItems, course);
190	    const fallbackTraining = hourItems
191	      .filter((item) => itemMatchesCourse(item, course))
192	      .reduce((sum, item) => sum + number(item.amount), 0);
193	    const trainingAmount = snapshot
194	      ? number(snapshot.trainingAmount)
195	      : fallbackTraining;
196	    const feeAmount = snapshot ? number(snapshot.feeAmount) : 0;
197	    return {
198	      name: course.name,
199	      code: course.code,
200	      ...hours,
201	      trainingAmount: roundMoney(trainingAmount),
202	      feeAmount: roundMoney(feeAmount),
203	      totalAmount: roundMoney(
204	        snapshot ? number(snapshot.totalAmount) : trainingAmount + feeAmount,
205	      ),
206	    };
207	  });
208	}
