210	function buildFees(balance: TrainingPlanQuoteBalanceInput) {
211	  return asRecords(balance.feeItems)
212	    .map(
213	      (fee): TrainingPlanQuoteFee => ({
214	        name:
215	          text(fee.productName) ||
216	          text(fee.label) ||
217	          text(fee.feeType) ||
218	          'Training fee',
219	        quantity: Math.max(1, number(fee.quantity) || 1),
220	        amount: roundMoney(number(fee.amount)),
221	      }),
222	    )
223	    .filter((fee) => fee.amount > 0);
224	}
225	
226	function buildPayments(
227	  balance: TrainingPlanQuoteBalanceInput,
228	  fundingDetails: JsonRecord,
229	  grandTotal: number,
230	) {
231	  const fundingModel = text(balance.fundingModel);
232	  const paymentSchedule = asRecord(fundingDetails.paymentSchedule);
233	  const installmentRows = asRecords(paymentSchedule.installments);
234	  if (installmentRows.length > 0) {
235	    return installmentRows.map(
236	      (installment, index): TrainingPlanQuotePayment => ({
237	        label: `Installment ${number(installment.sequence) || index + 1}`,
238	        dueDate: text(installment.dueDate) || null,
239	        amount: roundMoney(number(installment.amount)),
240	        percentage: number(installment.percentage),
241	      }),
242	    );
243	  }
244	
245	  const lenderSchedule = asRecord(fundingDetails.lenderFundingSchedule);
246	  const milestones = asRecords(lenderSchedule.milestones);
247	  if (fundingModel === 'lender' && milestones.length > 0) {
248	    const releaseMode =
249	      text(lenderSchedule.releaseMode) === 'percentage'
250	        ? 'percentage'
251	        : 'amount';
252	    const releaseAtStart =
253	      text(lenderSchedule.certificateReleaseEvent) !== 'checkride_complete';
254	    return milestones.map((milestone, index): TrainingPlanQuotePayment => {
255	      const percentage =
256	        milestone.percentage === null || milestone.percentage === undefined
257	          ? null
258	          : number(milestone.percentage);
259	      const amount =
260	        releaseMode === 'percentage'
261	          ? grandTotal * (number(percentage) / 100)
262	          : number(milestone.amount);
263	      const certificateName = text(milestone.certificateName);
264	      const thresholdHours = number(milestone.thresholdHours);
265	      return {
266	        label: certificateName
267	          ? `${certificateName} funding release`
268	          : `Lender release ${index + 1}`,
269	        dueDate: certificateName
270	          ? releaseAtStart
271	            ? 'When certificate begins'
272	            : 'When checkride is complete'
273	          : thresholdHours > 0
274	            ? `At ${thresholdHours.toFixed(1)} flight + sim hours`
275	            : null,
276	        amount: roundMoney(amount),
277	        percentage,
278	      };
279	    });
280	  }
281	
282	  return [];
283	}
