285	function getPaymentScheduleLabel(
286	  balance: TrainingPlanQuoteBalanceInput,
287	  fundingDetails: JsonRecord,
288	) {
289	  const fundingModel = text(balance.fundingModel);
290	  if (fundingModel === 'pay_as_you_go') return 'Pay as you go';
291	  if (fundingModel === 'lender') {
292	    const lenderSchedule = asRecord(fundingDetails.lenderFundingSchedule);
293	    return lenderSchedule.basis === 'certificate'
294	      ? 'Per certificate'
295	      : 'Flight + sim hour milestones';
296	  }
297	  const paymentSchedule = asRecord(fundingDetails.paymentSchedule);
298	  if (asRecords(paymentSchedule.installments).length > 0) {
299	    return paymentSchedule.mode === 'percentage'
300	      ? 'Percentage installments'
301	      : 'Fixed amount installments';
302	  }
303	  if (fundingModel === 'monthly_prepaid') return 'Monthly prepaid';
304	  return 'Payment schedule';
305	}
