307	export function createTrainingPlanOriginalQuoteSnapshot(
308	  balance: TrainingPlanQuoteBalanceInput,
309	  capturedAt: Date | string = new Date(),
310	): TrainingPlanOriginalQuoteSnapshot {
311	  const fundingDetails = asRecord(balance.fundingDetails);
312	  const trainingTotal = roundMoney(
313	    asRecords(balance.hourItems).reduce(
314	      (sum, item) => sum + number(item.amount),
315	      0,
316	    ),
317	  );
318	  const feeTotal = roundMoney(
319	    Number.isFinite(Number(balance.estimatedFeeTotal))
320	      ? number(balance.estimatedFeeTotal)
321	      : buildFees(balance).reduce((sum, fee) => sum + fee.amount, 0),
322	  );
323	  return {
324	    capturedAt:
325	      capturedAt instanceof Date
326	        ? capturedAt.toISOString()
327	        : new Date(capturedAt).toISOString(),
328	    trainingTotal,
329	    feeTotal,
330	    grandTotal: roundMoney(trainingTotal + feeTotal),
331	    flightHours: number(balance.flightHoursTotal),
332	    groundHours: number(balance.groundHoursTotal),
333	    simulatorHours: number(balance.simulatorHoursTotal),
334	    courseAllocations: asRecords(fundingDetails.courseAllocations).map(
335	      (allocation) => ({ ...allocation }),
336	    ),
337	  };
338	}
