340	export function buildTrainingPlanQuoteData({
341	  balance,
342	  logoUrl,
343	  schoolName,
344	  locationName,
345	  studentName,
346	  studentEmail,
347	  issueDate = new Date(),
348	  documentPrimaryColor,
349	  documentAccentColor,
350	}: BuildTrainingPlanQuoteDataInput): TrainingPlanQuotePdfProps {
351	  const fundingDetails = asRecord(balance.fundingDetails);
352	  const hourItems = asRecords(balance.hourItems);
353	  const fees = buildFees(balance);
354	  const trainingTotal = roundMoney(
355	    hourItems.reduce((sum, item) => sum + number(item.amount), 0),
356	  );
357	  const feeTotal = roundMoney(
358	    Number.isFinite(Number(balance.estimatedFeeTotal))
359	      ? number(balance.estimatedFeeTotal)
360	      : fees.reduce((sum, fee) => sum + fee.amount, 0),
361	  );
362	  const grandTotal = roundMoney(trainingTotal + feeTotal);
363	  const originalSnapshot = asRecord(fundingDetails.originalQuoteSnapshot);
364	  const originalGrandTotal =
365	    originalSnapshot.grandTotal === undefined
366	      ? grandTotal
367	      : roundMoney(number(originalSnapshot.grandTotal));
368	  const allocationAdjustmentTotal = roundMoney(grandTotal - originalGrandTotal);
369	  const certificates = buildCertificates(
370	    balance,
371	    fundingDetails,
372	    trainingTotal,
373	    feeTotal,
374	  );
375	  const payments = buildPayments(balance, fundingDetails, grandTotal);
376	  const shortId = balance.id.replace(/[^a-zA-Z0-9]/g, '').slice(0, 8);
377	
378	  return {
379	    logoUrl,
380	    schoolName,
381	    locationName,
382	    documentPrimaryColor: normalizeDocumentBrandColor(
383	      documentPrimaryColor,
384	      DEFAULT_DOCUMENT_PRIMARY_COLOR,
385	    ),
386	    documentAccentColor: normalizeDocumentBrandColor(
387	      documentAccentColor,
388	      DEFAULT_DOCUMENT_ACCENT_COLOR,
389	    ),
390	    studentName,
391	    studentEmail,
392	    quoteNumber: shortId.toUpperCase() || 'TRAINING',
393	    issueDate:
394	      toIsoDate(text(originalSnapshot.capturedAt)) ??
395	      toIsoDate(issueDate) ??
396	      new Date().toISOString().split('T')[0],
397	    startDate: toIsoDate(balance.startDate),
398	    planName: planName(balance),
399	    paymentSource:
400	      text(fundingDetails.paymentMethodLabel) ||
401	      text(fundingDetails.paymentVendorName) ||
402	      'Student funded',
403	    paymentScheduleLabel: getPaymentScheduleLabel(balance, fundingDetails),
404	    certificates,
405	    fees,
406	    payments,
407	    flightHours: number(balance.flightHoursTotal),
408	    groundHours: number(balance.groundHoursTotal),
409	    simulatorHours: number(balance.simulatorHoursTotal),
410	    trainingTotal,
411	    feeTotal,
412	    grandTotal,
413	    originalGrandTotal,
414	    allocationAdjustmentTotal,
415	    revisionUpdatedAt: toIsoDate(balance.updatedAt),
416	    notes: text(balance.notes) || null,
417	  };
418	}
