83	export function normalizeTrainingHourGuardrailSettings(
84	  value: unknown,
85	): TrainingHourGuardrailSettings {
86	  const raw =
87	    value && typeof value === 'object' && !Array.isArray(value)
88	      ? (value as Record<string, unknown>)
89	      : {};
90	  const rawThresholds =
91	    raw.warningThresholds &&
92	    typeof raw.warningThresholds === 'object' &&
93	    !Array.isArray(raw.warningThresholds)
94	      ? (raw.warningThresholds as Record<string, unknown>)
95	      : {};
96	  const rawMappings =
97	    raw.eventTypeMappings &&
98	    typeof raw.eventTypeMappings === 'object' &&
99	    !Array.isArray(raw.eventTypeMappings)
100	      ? (raw.eventTypeMappings as Record<string, unknown>)
101	      : {};
102	  const eventTypeMappings: Record<string, TrainingEventHourType> = {};
103	  for (const [eventTypeId, hourType] of Object.entries(rawMappings)) {
104	    if (
105	      hourType === 'flight' ||
106	      hourType === 'ground' ||
107	      hourType === 'simulator' ||
108	      hourType === 'non_training'
109	    ) {
110	      eventTypeMappings[eventTypeId] = hourType;
111	    }
112	  }
113	
114	  return {
115	    enabled: raw.enabled !== false,
116	    preventProjectedOverage: raw.preventProjectedOverage !== false,
117	    autoHoldAtLimit: raw.autoHoldAtLimit !== false,
118	    warningThresholds: {
119	      flight: finiteNonNegative(
120	        rawThresholds.flight,
121	        DEFAULT_TRAINING_HOUR_GUARDRAILS.warningThresholds.flight,
122	      ),
123	      ground: finiteNonNegative(
124	        rawThresholds.ground,
125	        DEFAULT_TRAINING_HOUR_GUARDRAILS.warningThresholds.ground,
126	      ),
127	      simulator: finiteNonNegative(
128	        rawThresholds.simulator,
129	        DEFAULT_TRAINING_HOUR_GUARDRAILS.warningThresholds.simulator,
130	      ),
131	    },
132	    eventTypeMappings,
133	  };
134	}
