176	export function hasAutomaticFlightBillingMethod(input: {
177	  preference: AutomaticFlightBillingPreference | null | undefined;
178	  methods: AutomaticFlightBillingMethod[];
179	}) {
180	  const source =
181	    input.preference?.source === 'card' || input.preference?.source === 'smart'
182	      ? input.preference.source
183	      : input.preference?.source === 'balance'
184	        ? 'balance'
185	        : input.preference?.autopayEnabled
186	          ? 'card'
187	          : 'balance';
188	  if (source === 'balance') return false;
189	
190	  const selected =
191	    (input.preference?.defaultCardId
192	      ? input.methods.find(
193	          (method) => method.id === input.preference?.defaultCardId,
194	        )
195	      : null) ??
196	    input.methods.find((method) => method.isDefault) ??
197	    input.methods[0] ??
198	    null;
199	
200	  return Boolean(
201	    selected?.stripePaymentMethodId &&
202	      !selected.isBlocked &&
203	      selected.isVerified !== false &&
204	      ((selected.type ?? 'card') === 'card' ||
205	        selected.type === 'us_bank_account'),
206	  );
207	}
