209	export function parseTrainingAllocationHoldMetadata(
210	  notes: unknown,
211	): TrainingAllocationHoldMetadata | null {
212	  if (typeof notes !== 'string' || !notes.trim()) return null;
213	  let parsed: unknown;
214	  try {
215	    parsed = JSON.parse(notes);
216	  } catch {
217	    // Older records appended a plain-text resolution after the JSON payload.
218	    try {
219	      parsed = JSON.parse(notes.split('\n')[0] ?? '');
220	    } catch {
221	      return null;
222	    }
223	  }
224	  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
225	    return null;
226	  }
227	  const value = parsed as Record<string, unknown>;
228	  const hourType =
229	    value.hourType === 'flight' ||
230	    value.hourType === 'ground' ||
231	    value.hourType === 'simulator'
232	      ? value.hourType
233	      : null;
234	  if (
235	    value.source !== 'training_hour_guardrail' ||
236	    !hourType ||
237	    typeof value.balanceId !== 'string' ||
238	    typeof value.courseAllocationId !== 'string' ||
239	    typeof value.courseName !== 'string'
240	  ) {
241	    return null;
242	  }
243	  const rawResolution =
244	    value.resolution &&
245	    typeof value.resolution === 'object' &&
246	    !Array.isArray(value.resolution)
247	      ? (value.resolution as Record<string, unknown>)
248	      : null;
249	  const method =
250	    rawResolution?.method === 'allocation_adjustment' ||
251	    rawResolution?.method === 'admin_approval' ||
252	    rawResolution?.method === 'system'
253	      ? rawResolution.method
254	      : null;
255	  const resolution: TrainingAllocationHoldResolution | undefined =
256	    rawResolution &&
257	    method &&
258	    typeof rawResolution.explanation === 'string' &&
259	    typeof rawResolution.resolvedAt === 'string' &&
260	    typeof rawResolution.resolvedBy === 'string'
261	      ? {
262	          explanation: rawResolution.explanation,
263	          resolvedAt: rawResolution.resolvedAt,
264	          resolvedBy: rawResolution.resolvedBy,
265	          method,
266	        }
267	      : undefined;
268	
269	  return {
270	    source: 'training_hour_guardrail',
271	    balanceId: value.balanceId,
272	    courseAllocationId: value.courseAllocationId,
273	    courseName: value.courseName,
274	    hourType,
275	    usedHours: finiteNonNegative(value.usedHours, 0),
276	    allottedHours: finiteNonNegative(value.allottedHours, 0),
277	    ...(resolution ? { resolution } : {}),
278	  };
279	}
