326	export function getActiveTrainingPlanCourseAllocation(
327	  fundingDetails: Record<string, unknown> | null | undefined,
328	): TrainingPlanCourseAllocation | null {
329	  const allocations = getTrainingPlanCourseAllocations(fundingDetails);
330	  if (allocations.length === 0) return null;
331	  const rawIndex = Number(fundingDetails?.currentCourseIndex);
332	  if (Number.isInteger(rawIndex)) {
