364	export function evaluateTrainingHourGuardrail(input: {
365	  studentId: string;
366	  balanceId: string;
367	  fundingDetails: Record<string, unknown> | null | undefined;
368	  hourType: TrainingHourType;
369	  proposedHours: number;
370	  preventProjectedOverage?: boolean;
371	}): TrainingHourGuardrailIssue | null {
372	  const allocation = getActiveTrainingPlanCourseAllocation(
373	    input.fundingDetails,
374	  );
375	  if (!allocation) return null;
376	  const { used, total } = allocationHours(allocation, input.hourType);
377	  if (total <= 0) return null;
378	
379	  const proposedHours = finiteNonNegative(input.proposedHours, 0);
380	  const remainingHours = Math.max(0, total - used);
381	  const allocationReached = used >= total;
382	  const projectedOverage =
383	    input.preventProjectedOverage !== false &&
384	    proposedHours > remainingHours + 0.0001;
385	  if (!allocationReached && !projectedOverage) return null;
386	
387	  return {
388	    studentId: input.studentId,
389	    balanceId: input.balanceId,
390	    courseAllocationId: allocation.id,
391	    courseName: allocation.name,
392	    hourType: input.hourType,
393	    usedHours: used,
394	    allottedHours: total,
395	    remainingHours,
396	    proposedHours,
397	    projectedHours: used + proposedHours,
398	    reason: allocationReached ? 'allocation_reached' : 'projected_overage',
399	  };
400	}
