1	/**
2	 * FAA pilot currency helpers.
3	 *
4	 * Thin computational layer — every function is pure. All DB access happens
5	 * outside this file; the FRC prefill route fetches logbook rows for a
6	 * student and passes them in. That keeps these helpers trivial to unit-test
7	 * (no mocking) and reusable from other flows (e.g. a future admin report).
8	 *
9	 * Regulatory citations:
10	 *   • 14 CFR 61.56  — flight review, every 24 calendar months
11	 *   • 14 CFR 61.57(a) — day landing currency: 3 T/O + 3 landings in last 90 days
12	 *   • 14 CFR 61.57(b) — night landing currency: 3 T/O + 3 landings to a full
13	 *                        stop between 1 hr after sunset and 1 hr before sunrise
14	 *   • 14 CFR 61.57(c) — instrument currency: 6 approaches + holding + tracking
15	 *                        in last 6 calendar months
16	 *
17	 * Limitations (documented deliberately, not bugs):
18	 *   - We approximate 61.57(c) by counting `approaches` from logbook rows.
19	 *     The full rule also requires holding procedures, intercepting/tracking
20	 *     courses — we don't have structured data for those. The prefill marks
21	 *     a pilot "IFR current" only if approaches ≥ 6 AND they have logged any
22	 *     instrument time in the window (a weak but useful filter).
23	 *   - 61.57(a) / (b) technically require same category, class, and type.
24	 *     We compute the raw totals here; callers that need per-aircraft scoping
25	 *     should pre-filter the entries they pass in.
26	 */
27	
28	/** Minimum shape of a logbook entry needed for currency calculations. */
29	export interface CurrencyLogbookEntry {
30	  date: Date;
31	  totalTime: number | null;
32	  dayLandings: number | null;
33	  nightLandings: number | null;
34	  approaches: number | null;
35	  instrument: number | null;
36	}
37	
38	/** Answer returned for each currency question. Booleans are strict yes/no. */
39	export interface CurrencyFlags {
40	  /** ≥3 day landings in preceding 90 days. */
41	  daytimeLandingCurrent: boolean;
42	  /** ≥3 night landings in preceding 90 days. */
43	  nighttimeLandingCurrent: boolean;
44	  /** ≥6 approaches AND >0 instrument time in preceding 6 calendar months. */
45	  ifrCurrent: boolean;
46	  /** Raw counts so UI can display "3 of 3" progress indicators. */
47	  dayLandings90: number;
48	  nightLandings90: number;
49	  approaches6mo: number;
50	  instrumentHours6mo: number;
51	}
52	
53	/** Sum a field over entries dated within `daysBack` of `now`. */
54	function sumWithin(
55	  entries: CurrencyLogbookEntry[],
56	  now: Date,
57	  daysBack: number,
58	  pick: (e: CurrencyLogbookEntry) => number | null,
59	): number {
60	  const cutoff = new Date(now.getTime() - daysBack * 24 * 60 * 60 * 1000);
61	  let total = 0;
62	  for (const e of entries) {
63	    if (e.date >= cutoff && e.date <= now) {
64	      const v = pick(e);
65	      if (typeof v === 'number' && !Number.isNaN(v)) total += v;
66	    }
67	  }
68	  return total;
69	}
70	
71	/**
72	 * Compute pilot currency flags from a set of logbook entries.
73	 *
74	 * Entries need not be pre-filtered by date — this function does the
75	 * windowing itself. Callers must pass the student's entries only (the
76	 * caller is responsible for tenant + student scoping).
77	 */
78	export function computeCurrency(
79	  entries: CurrencyLogbookEntry[],
80	  now: Date = new Date(),
81	): CurrencyFlags {
82	  const dayLandings90 = sumWithin(entries, now, 90, (e) => e.dayLandings);
83	  const nightLandings90 = sumWithin(entries, now, 90, (e) => e.nightLandings);
84	  // 61.57(c) says "within the preceding 6 calendar months" — we approximate
85	  // with 183 days, which is consistent with how other FAA systems treat it.
86	  const approaches6mo = sumWithin(entries, now, 183, (e) => e.approaches);
87	  const instrumentHours6mo = sumWithin(entries, now, 183, (e) => e.instrument);
88	
89	  return {
90	    daytimeLandingCurrent: dayLandings90 >= 3,
91	    nighttimeLandingCurrent: nightLandings90 >= 3,
92	    ifrCurrent: approaches6mo >= 6 && instrumentHours6mo > 0,
93	    dayLandings90,
94	    nightLandings90,
95	    approaches6mo,
96	    instrumentHours6mo,
97	  };
98	}
99	
100	/**
101	 * Is `expiry` still in the future (strictly greater than `now`)?
102	 * Null expiry → null answer (unknown); callers can decide how to surface.
103	 */
104	export function isDateCurrent(
105	  expiry: Date | null | undefined,
106	  now: Date = new Date(),
107	): boolean | null {
108	  if (!expiry) return null;
109	  return expiry.getTime() > now.getTime();
110	}
111	
112	/**
113	 * Sum total flight time across all entries. Nulls are skipped.
114	 */
115	export function sumTotalTime(entries: CurrencyLogbookEntry[]): number {
116	  let total = 0;
117	  for (const e of entries) {
118	    if (typeof e.totalTime === 'number' && !Number.isNaN(e.totalTime)) {
119	      total += e.totalTime;
120	    }
121	  }
122	  return total;
123	}
